<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/header.php';
if($_SESSION['user']['role']!=='admin'){http_response_code(403);die('Access denied');}$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$id=(int)$_POST['product_id'];$q=(float)$_POST['quantity'];if($q<=0)throw new Exception('Quantity lazima iwe zaidi ya sifuri.');$pdo->beginTransaction();$s=$pdo->prepare('UPDATE products SET stock_qty=stock_qty+? WHERE id=?');$s->execute([$q,$id]);$s=$pdo->prepare("INSERT INTO stock_movements(product_id,movement_type,quantity,note,user_id) VALUES(?,'IN',?,?,?)");$s->execute([$id,$q,trim($_POST['note'])?:'Stock addition',$_SESSION['user']['id']]);$pdo->commit();$msg='Stock imeongezwa.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}}
$products=$pdo->query('SELECT * FROM products WHERE active=1 ORDER BY category,name')->fetchAll();?><h2>Inventory / Stock</h2><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert danger"><?=e($err)?></div><?php endif;?><div class="card"><h3>Ongeza Stock</h3><form method="post" class="grid"><div><label>Bidhaa</label><select name="product_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> — Stock: <?=e($p['stock_qty'])?></option><?php endforeach;?></select></div><div><label>Quantity</label><input type="number" step="0.01" min="0.01" name="quantity" required></div><div><label>Maelezo</label><input name="note"></div><div><label>&nbsp;</label><button class="green">Ongeza Stock</button></div></form></div><br><div class="card"><table><tr><th>Category</th><th>Bidhaa</th><th>Bei</th><th>Stock</th><th>Reorder Level</th></tr><?php foreach($products as $p):?><tr><td><?=e($p['category'])?></td><td><?=e($p['name'])?></td><td>TSh <?=number_format($p['price'])?></td><td><?=e($p['stock_qty'])?></td><td><?=e($p['reorder_level'])?></td></tr><?php endforeach;?></table></div><?php require_once __DIR__.'/../config/footer.php';?>
